"""User settings, a small JSON file. SHELF_SETTINGS overrides the location."""
import json
import os
import tempfile
from pathlib import Path

SORT_KEYS = ("title", "author")
DEFAULTS = {"sort": "title"}


def path():
    env = os.environ.get("SHELF_SETTINGS")
    return Path(env) if env else Path.home() / ".shelf" / "settings.json"


def load():
    out = dict(DEFAULTS)
    try:
        data = json.loads(path().read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return out
    if isinstance(data, dict) and data.get("sort") in SORT_KEYS:
        out["sort"] = data["sort"]
    return out


def save(sort):
    if sort not in SORT_KEYS:
        raise ValueError("sort must be one of %s" % ", ".join(SORT_KEYS))
    p = path()
    p.parent.mkdir(parents=True, exist_ok=True)
    data = {"sort": sort}
    # atomic: temp file in the same dir, then replace
    fd, tmp = tempfile.mkstemp(dir=p.parent, prefix=".settings-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f)
        os.replace(tmp, p)
    except BaseException:
        os.unlink(tmp)
        raise
    return data

