def test_serve_binds_loopback_and_exits_on_ctrl_c(capsys, monkeypatch):
    calls = []

    class Fake:
        def serve_forever(self):
            raise KeyboardInterrupt

        def server_close(self):
            calls.append("closed")

    def fake_make_server(host="127.0.0.1", port=8000):
        calls.append((host, port))
        return Fake()

    from shelf import web
    monkeypatch.setattr(web, "make_server", fake_make_server)
    assert cli.main(["serve", "--port", "8765"]) == 0
    assert calls == [("127.0.0.1", 8765), "closed"]
    assert capsys.readouterr().out == "Settings page: http://127.0.0.1:8765/\n"


